import{d as l,C as s,o as g,c as d,j as i,a,E as e,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"中庸·第19章","description":"《中庸》第 19 章——武王周公其达孝：善继人之志、善述人之事；宗庙诸礼所以序昭穆、辨贵贱、辨贤、逮贱、序齿；明乎郊社禘尝，治国如示诸掌。","frontmatter":{"title":"中庸·第19章","description":"《中庸》第 19 章——武王周公其达孝：善继人之志、善述人之事；宗庙诸礼所以序昭穆、辨贵贱、辨贤、逮贱、序齿；明乎郊社禘尝，治国如示诸掌。","category":"guide","aliases":["第19章","中庸第19章","达孝"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-19.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-19.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-19.md"},z=l({...u,setup(p){const o=[{id:"daxiao",label:"武王周公其达孝矣乎 · 善继志，善述事",showLabel:!0,sentences:[["子曰：“武王、周公，其",{text:"达孝",glossary:"daxiao"},"矣乎！夫孝者：",{text:"善继人之志",glossary:"jizhi"},"，",{text:"善述人之事",glossary:"shushi"},"者也。"]],note:"孔子说：武王、周公大概是「达孝」（通于天下之孝）了吧！所谓孝，在于「善继人之志，善述人之事」——善于继承先人的志向，善于绍述先人的事业。此句是「孝」的界说，也是全章纲领。"},{id:"jizu",label:"春秋修其祖庙 · 陈宗器，设裳衣，荐时食",showLabel:!0,sentences:[["春秋修其祖庙，陈其",{text:"宗器",glossary:"zongqi"},"，设其",{text:"裳衣",glossary:"shangyi"},"，荐其",{text:"时食",glossary:"shishi"},"。"]],note:"具体祭礼：「春秋修其祖庙」——四时修缮祖庙；「陈其宗器」——陈列宗庙的祭器；「设其裳衣」——摆出先人的衣冠；「荐其时食」——进献应时的食物。"},{id:"zhuli",label:"序昭穆 · 序爵序事 · 旅酬 · 燕毛",showLabel:!0,sentences:[["宗庙之礼，所以",{text:"序昭穆",glossary:"zhaomu"},"也；",{text:"序爵",glossary:"xujue"},"，所以辨贵贱也；",{text:"序事",glossary:"xushi"},"，所以辨贤也；",{text:"旅酬",glossary:"lüchou"},"下为上，所以",{text:"逮贱",glossary:"daijian"},"也；",{text:"燕毛",glossary:"yanmao"},"，所以",{text:"序齿",glossary:"xuchi"},"也。"]],note:"宗庙之礼的五项功用：「序昭穆」（左右昭穆，辨亲疏之序），「序爵」（按爵位，辨贵贱），「序事」（按所司之职，辨贤能），「旅酬下为上」（众人旅酬劝酒时让下位者先饮，使卑贱者也能与，故「所以逮贱也」），「燕毛」（宴饮时以须发之色定座次，故「所以序齿也」——序年齿）。"},{id:"xiaozhi",label:"践其位 · 事死如事生 · 治国其如示诸掌",showLabel:!0,sentences:[["践其位，行其礼，奏其乐，敬其所尊，爱其所亲，事死如事生，事亡如事存，孝之至也。"],["郊社之礼，所以事上帝也；宗庙之礼，所以祀乎其先也。明乎郊社之礼、",{text:"禘尝",glossary:"dichang"},"之义，治国其如",{text:"示诸掌",glossary:"shizhuzhang"},"乎。”"]],note:"「践其位，行其礼，奏其乐，敬其所尊，爱其所亲，事死如事生，事亡如事存」——这便是「孝之至也」。又：郊社之礼所以事上帝，宗庙之礼所以祀先祖；「明乎郊社之礼、禘尝之义，治国其如示诸掌乎」——明白祭祀之义，治国便如看自己的手掌。"}],r=[{id:"daxiao",term:"达孝",pinyin:"dá xiào",meaning:"朱注：「达，通也。承上章而言武王、周公之孝，乃天下之人通谓之孝。」即孝之通义。"},{id:"jizhi",term:"善继人之志",pinyin:"shàn jì rén zhī zhì",meaning:"善于继承前人的志向。朱注以此为「继志述事之大者」。"},{id:"shushi",term:"善述人之事",pinyin:"shàn shù rén zhī shì",meaning:"善于继述前人的事业。"},{id:"zongqi",term:"宗器",pinyin:"zōng qì",meaning:"先世所藏的重器。朱注举周之赤刀、大训、天球、河图之属。"},{id:"shangyi",term:"裳衣",pinyin:"cháng yī",meaning:"先祖遗下的衣服，祭时设之以授尸。"},{id:"shishi",term:"时食",pinyin:"shí shí",meaning:"四时之食，各有其物。"},{id:"zhaomu",term:"序昭穆",pinyin:"xù zhāo mù",meaning:"按昭穆之次排列。宗庙之次：左为昭，右为穆，子孙亦以为序。"},{id:"xujue",term:"序爵",pinyin:"xù jué",meaning:"按爵位排列，所以辨贵贱。"},{id:"xushi",term:"序事",pinyin:"xù shì",meaning:"按职事排列，所以辨贤能。"},{id:"lüchou",term:"旅酬",pinyin:"lǚ chóu",meaning:"旅：众；酬：导饮。众人相酬饮之礼。"},{id:"daijian",term:"逮贱",pinyin:"dài jiàn",meaning:"及于卑贱者。朱注：「宗庙之中以有事为荣，故逮及贱者，使亦得以申其敬也。」"},{id:"yanmao",term:"燕毛",pinyin:"yàn máo",meaning:"祭毕而宴，以毛发之色别长幼为坐次。"},{id:"xuchi",term:"序齿",pinyin:"xù chǐ",meaning:"按年齿排列。齿：年数。"},{id:"dichang",term:"禘尝",pinyin:"dì cháng",meaning:"禘：天子宗庙之大祭，追祭太祖所自出，以太祖配之；尝：秋祭。举此以概四时之祭。"},{id:"shizhuzhang",term:"示诸掌",pinyin:"shì zhū zhǎng",meaning:"示：同「视」。视诸掌，言易见——治国之易，如在掌上。"}];return(y,n)=>{const h=s("DaoTextReading"),t=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第19章",tabindex:"-1"},[a("中庸·第19章 "),i("a",{class:"header-anchor",href:"#中庸·第19章","aria-label":'Permalink to "中庸·第19章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第十九章承上章而言武王、周公之「"),i("strong",null,"达孝"),a("」：孝不在服侍，而在「"),i("strong",null,"善继人之志，善述人之事"),a("」；接着铺陈宗庙祭祀之礼，落到「事死如事生」与「治国其如示诸掌」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),e(h,{colophon:"达孝 · 继志述事 · 祭祀之礼 · 示诸掌",tone:"ink",sections:o,glossary:r,"default-mode":"slips","aria-label":"中庸·第19章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(t,{items:[{term:"达孝",pinyin:["dá","xiào"],meaning:"朱注：「达，通也。」天下之人通谓之孝——孝之通义。"},{term:"善继人之志",pinyin:["shàn","jì","rén","zhī","zhì"],meaning:"善于继承前人的志向。"},{term:"善述人之事",pinyin:["shàn","shù","rén","zhī","shì"],meaning:"善于继述前人的事业。"},{term:"宗器",pinyin:["zōng","qì"],meaning:"先世所藏的重器。"},{term:"裳衣",pinyin:["cháng","yī"],meaning:"先祖遗下的衣服。"},{term:"时食",pinyin:["shí","shí"],meaning:"四时的食物。三者皆祭祀所陈。"}]}),e(t,{items:[{term:"序昭穆",pinyin:["xù","zhāo","mù"],meaning:"按昭穆排列（左昭右穆），序亲疏。"},{term:"序爵",pinyin:["xù","jué"],meaning:"按爵位排列，辨贵贱。"},{term:"序事",pinyin:["xù","shì"],meaning:"按职事排列，辨贤能——礼把人各安其位。"},{term:"旅酬",pinyin:["lǚ","chóu"],meaning:"众人相酬饮，使卑贱者亦得申其敬。"},{term:"燕毛",pinyin:["yàn","máo"],meaning:"宴时以头发颜色定长幼之序。"},{term:"示诸掌",pinyin:["shì","zhū","zhǎng"],meaning:"示同「视」。视诸掌，言易见——明乎礼之义，治国如在掌上。"}]}),n[4]||(n[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>武王周公其达孝矣乎</strong>：孔子说：「武王、周公，真是通称的孝啊！所谓孝，就是善于继承前人的志向、善于继述前人的事业。」</p><p><strong>春秋修其祖庙</strong>：春秋时修葺祖庙，陈设先世的宗器，摆设先祖的遗衣，进献四时的食物。</p><p><strong>序昭穆 · 序爵序事 · 旅酬 · 燕毛</strong>：宗庙之礼，是用来排列昭穆的；序爵位，是分辨贵贱的；序职事，是分辨贤能的；旅酬时由下而上，是使卑贱者也能与祭的；宴饮时按头发颜色，是排列长幼的。</p><p><strong>践其位 · 事死如事生</strong>：踏着先王的位置，行先王的礼，奏先王的乐，敬先王所尊，爱先王所亲，事死者如事生者，事亡者如事存者——这是孝的极至。郊社之礼，是用来事奉上帝的；宗庙之礼，是用来祭祀祖先的。明白了郊社之礼与禘尝之义，治国就像看自己的手掌一样容易了。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十九章接着上章讲武王、周公，但给「孝」下了一个新的定义：<strong>善继人之志，善述人之事</strong>——孝不在服侍，在承接。</p><p>接下来铺陈祭祀之礼：修祖庙、陈宗器、设裳衣、荐时食；然后说这套礼的次序作用——序昭穆（亲疏）、序爵（贵贱）、序事（贤能）、旅酬（逮贱）、燕毛（长幼）。最后收到「事死如事生」与「明乎郊社之礼、禘尝之义，治国其如示诸掌」。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「继志述事」把孝从关系抬到事业</strong>：朱注说上章武王「缵绪」、周公「成德」正是「继志述事之大者」。孝不是守在身边，而是<strong>把上一代要做的事接着做完</strong>。</li><li><strong>祭祀之礼是一套「安放人」的制度</strong>：昭穆定亲疏、爵定贵贱、事定贤能、旅酬使卑贱者不遗、燕毛定长幼。<strong>礼的用处，是让每个人在同一个场合里都知道自己该在哪里</strong>——这也是它「序」字当头的缘故。</li><li><strong>「事死如事生」是这一章的心</strong>：把对生者的敬意，原样移到死者身上。</li><li><strong>「治国其如示诸掌」把礼推到政治</strong>：懂了礼之义，治国就不难——因为礼本就是把人和事安排妥当的功夫。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>孝的现代读法</strong>：不只是照顾，更是把上一代的心愿与事业接下去。</li><li><strong>次序感</strong>：一个场合里，谁先谁后、谁主谁次，礼的价值在这里——不是等级，是不乱。</li><li><strong>「事死如事生」</strong>：对已经不在的人与事，是否还保持着同样的敬。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：武王、周公的孝，是天下人都认可的孝。什么叫孝？——<strong>善于继承前人的志向，善于接续前人的事业。</strong></p><p>接着他细数宗庙之礼：修庙、陈器、设衣、荐食；而这一套礼真正的用处，在于<strong>排序</strong>——亲疏有昭穆，贵贱有爵位，贤能有职事，卑贱者也能参与，长幼有先后。</p><p>最后落到两句话：<strong>事死如事生</strong>，以及<strong>明白了祭天祭祖之义，治国就像看自己的手掌</strong>。</p><p>这两句话把「孝」从一家之内，推到了天下。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「善继人之志，善述人之事」——我要接的「志」和「事」，具体是什么？</li><li>「事死如事生」——对已经不在的人、已经结束的事，我还保持着同样的敬吗？</li><li>礼的排序作用（昭穆／爵／事／齿）——我所在的组织或场合里，次序乱在哪里？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-18">中庸·第18章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-20">中庸·第20章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',25))])}}});export{x as __pageData,z as default};
